import base64
import hashlib
import json
import subprocess
import zipfile
import zlib
from pathlib import Path

# Transfer the exact locally tested source diff, not a second implementation.
DATA = ""
payload = json.loads(zlib.decompress(base64.b64decode(DATA)))
baseline = 'cc738752127851fff55f2a6c931719b7336210fa'
subprocess.run(['git', 'fetch', '--no-tags', '--depth=1', 'origin', baseline], check=True)
subprocess.run(['git', 'config', 'core.autocrlf', 'false'], check=True)
for name in payload['base']:
    raw = subprocess.check_output(['git', 'show', baseline + ':' + name])
    Path(name).write_bytes(raw.replace(b'\r\n', b'\n'))
subprocess.run(['git', 'apply', '--whitespace=nowarn', '-'], input=payload['diff'].encode('utf-8'), check=True)
for name, expected in payload['expected'].items():
    path = Path(name)
    normalized = path.read_bytes().replace(b'\r\n', b'\n')
    path.write_bytes(normalized)
    if hashlib.sha256(normalized).hexdigest() != expected:
        raise RuntimeError('Tested-source checksum mismatch: ' + name)
print('Installed and verified exact tested source:', len(payload['expected']), 'files')
Path('release').mkdir(exist_ok=True)
with zipfile.ZipFile('release/review-source.zip', 'w', zipfile.ZIP_DEFLATED) as archive:
    for directory in ['src', 'tests', 'docs', '.github', 'scripts']:
        for path in Path(directory).rglob('*'):
            if path.is_file() and not any(part in path.parts for part in ['bin', 'obj', '__pycache__']):
                archive.write(path, path.as_posix())
    for name in ['Directory.Build.props', 'Directory.Packages.props', 'MyLovePixel.slnx', 'global.json', 'HANDOFF.md', 'README.md', 'THIRD_PARTY_NOTICES.md']:
        if Path(name).is_file():
            archive.write(name)
